      for (size_t j = 1; j <= shared.dim.P.dim[1]; ++j) {
        state[i - 1 + (j - 1) * shared.dim.P.mult[1] + shared.odin.offset.state[39]] = shared.P0[i - 1 + (j - 1) * shared.dim.P0.mult[1]];
      }
